(() => {
  "use strict";
  const root = document.querySelector("[data-panel-app]");
  const tokenKey = "prisma-panel-session";
  const esc = (value = "") => String(value).replace(/[&<>"']/g, (char) => ({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[char]));
  const api = async (path, options = {}) => {
    const token = sessionStorage.getItem(tokenKey);
    const headers = new Headers(options.headers || {});
    if (token) headers.set("Authorization", `Bearer ${token}`);
    if (options.body && !(options.body instanceof FormData) && !headers.has("Content-Type")) headers.set("Content-Type", "application/json");
    const response = await fetch(path, {...options, headers});
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || "Não foi possível concluir a operação.");
    return data;
  };
  const shell = (content) => `<div class="panel-shell"><aside class="panel-sidebar"><a class="brand panel-brand" href="/"><span class="brand-word">PRISMA</span><span class="panel-brand-label">Editorial</span></a><p class="panel-sidebar__eyebrow">Gestão de conteúdo</p><nav class="panel-nav"><a href="/painel/" aria-current="page"><span><strong>Cases</strong><small>Portfólio das frentes</small></span></a><a href="/" target="_blank"><span><strong>Ver site</strong><small>Abrir uma nova aba</small></span></a></nav><div class="panel-sidebar__bottom"><div class="panel-theme"><p>Versão visual</p><div class="theme-switcher"><button class="theme-choice" data-theme-choice="golden">Golden</button><button class="theme-choice" data-theme-choice="solar">Solar</button></div></div><div class="panel-user"><span class="panel-user__avatar">P</span><span class="panel-user__identity"><strong>Equipe Prisma</strong><small>Acesso editorial</small></span><button class="panel-logout" type="button" data-logout title="Sair">↪</button></div></div></aside><div class="panel-main">${content}</div></div>`;
  const input = (id, name, label, value, opts = "") => `<div class="panel-field ${opts}"><label for="${id}">${label} <span>*</span></label><input class="panel-control" id="${id}" name="${name}" value="${esc(value)}"></div>`;
  const caseForm = (item = {}) => `<main class="panel-page"><header class="panel-page-header panel-editor-header"><div><a class="panel-back-link" href="/painel/">← Voltar para cases</a><p class="panel-kicker">${item.slug ? "Editar case" : "Novo case"}</p><h1>${item.slug ? "Ajustar o case." : "Criar um case."}</h1><p>Associe o trabalho à frente principal e publique apenas informações autorizadas.</p></div></header><form data-case-form><div class="panel-editor"><div><section class="panel-form-section"><header class="panel-form-section__header"><span>01</span><div><h2>Posicionamento</h2><p>O que vai aparecer na listagem de cases.</p></div></header><div class="panel-form-grid"><div class="panel-field"><label for="id_front">Frente <span>*</span></label><select class="panel-control panel-select" id="id_front" name="front" required><option value="">Selecione</option><option value="marketing" ${item.front === "marketing" ? "selected" : ""}>Marketing</option><option value="tecnologia" ${item.front === "tecnologia" ? "selected" : ""}>Tecnologia</option></select></div><div class="panel-field"><label for="id_status">Status <span>*</span></label><select class="panel-control panel-select" id="id_status" name="status"><option value="draft" ${item.status !== "published" ? "selected" : ""}>Rascunho</option><option value="published" ${item.status === "published" ? "selected" : ""}>Publicado</option></select></div><div class="panel-field panel-field--full"><div class="panel-field__label-row"><label for="id_title">Título <span>*</span></label><span data-count-for="id_title">0 / 120</span></div><input class="panel-control" id="id_title" name="title" maxlength="120" required value="${esc(item.title)}"></div>${input("id_category", "category", "Categoria", item.category)}${input("id_deliverables", "deliverables", "Entregáveis", item.deliverables)}<div class="panel-field panel-field--full"><div class="panel-field__label-row"><label for="id_summary">Resumo <span>*</span></label><span data-count-for="id_summary">0 / 240</span></div><textarea class="panel-control" id="id_summary" name="summary" maxlength="240" required>${esc(item.summary)}</textarea></div></div></section><section class="panel-form-section"><header class="panel-form-section__header"><span>02</span><div><h2>Imagens do case</h2><p>Envie até cinco imagens JPG, PNG, WebP ou AVIF. Máximo de 8 MB por arquivo.</p></div></header><div class="panel-field panel-field--full"><label for="id_images">Galeria</label><input class="panel-control panel-file" id="id_images" type="file" accept="image/jpeg,image/png,image/webp,image/avif" multiple><p class="panel-field__help">As imagens aparecerão em uma galeria com rolagem na página do case.</p><div class="panel-media-grid" data-media-grid></div></div></section><section class="panel-form-section"><header class="panel-form-section__header"><span>03</span><div><h2>História do projeto</h2><p>Contexto que aparece na página individual do case.</p></div></header><div class="panel-form-grid panel-form-grid--narrative"><div class="panel-field"><label for="id_challenge">O desafio <span>*</span></label><textarea class="panel-control" id="id_challenge" name="challenge" required>${esc(item.challenge)}</textarea></div><div class="panel-field"><label for="id_solution">A solução <span>*</span></label><textarea class="panel-control" id="id_solution" name="solution" required>${esc(item.solution)}</textarea></div><div class="panel-field panel-field--full"><label for="id_external_url">Link do botão Acessar <span class="optional">opcional</span></label><input class="panel-control" id="id_external_url" name="external_url" type="url" value="${esc(item.external_url)}" placeholder="https://"></div><label class="panel-checkbox-field panel-field--full"><input class="panel-checkbox" name="featured" type="checkbox" ${item.featured ? "checked" : ""}><span><strong>Destacar no portfólio</strong><span>O case recebe maior evidência na grade.</span></span></label></div></section><p class="panel-form-alert" hidden data-form-error></p><div class="panel-form-actions"><a class="panel-cancel" href="/painel/">Cancelar</a><button class="button" type="submit">${item.slug ? "Salvar alterações" : "Criar case"} <span>↗</span></button></div></div><aside class="panel-editor__summary"><div class="panel-editor-summary-card"><span class="panel-summary-front" data-summary-front>Frente do case</span><h2 data-summary-title>Case sem título</h2><dl><div><dt>Status</dt><dd data-summary-status>Rascunho</dd></div><div><dt>Imagens</dt><dd data-summary-images>0 / 5</dd></div></dl><p class="panel-editor-summary-card__note">A galeria fica disponível para todos os cases publicados.</p></div></aside></div></form></main>`;
  function controls() {
    document.querySelector("[data-logout]")?.addEventListener("click", () => { sessionStorage.removeItem(tokenKey); login(); });
    document.querySelectorAll("[data-theme-choice]").forEach((button) => button.addEventListener("click", () => { document.documentElement.dataset.theme = button.dataset.themeChoice; localStorage.setItem("prisma-theme", button.dataset.themeChoice); }));
  }
  function drawMedia(grid, images, refresh) {
    grid.innerHTML = images.length ? images.map((image, index) => `<figure class="panel-media-card"><img src="${esc(image.preview || image.url)}" alt=""><figcaption><span>Imagem ${index + 1}</span><button type="button" data-remove-image="${index}">Remover</button></figcaption></figure>`).join("") : '<p class="panel-media-empty">Nenhuma imagem adicionada. A galeria é opcional.</p>';
    grid.querySelectorAll("[data-remove-image]").forEach((button) => button.addEventListener("click", () => { images.splice(Number(button.dataset.removeImage), 1); refresh(); }));
  }
  async function dashboard() {
    try {
      const {cases} = await api("/api/cases");
      const cards = cases.length ? cases.map((item) => `<article class="panel-project"><div class="panel-project__visual">${item.images?.[0] ? `<img src="${esc(item.images[0].url)}" alt="">` : '<div class="panel-project__art"><span></span></div>'}</div><div class="panel-project__body"><div class="panel-project__badges"><span class="panel-badge">${item.front === "marketing" ? "Marketing" : "Tecnologia"}</span><span class="panel-badge panel-badge--${item.status}">${item.status === "published" ? "Publicado" : "Rascunho"}</span></div><h3>${esc(item.title)}</h3><p>${esc(item.summary)}</p><div class="panel-project__meta"><span>${esc(item.category)}</span><span>${item.images?.length || 0} imagem(ns)</span></div></div><div class="panel-project__actions"><button class="panel-action panel-action--primary" data-edit="${esc(item.slug)}">Editar →</button><a class="panel-action" href="/case.html?slug=${encodeURIComponent(item.slug)}" target="_blank">Ver página ↗</a></div></article>`).join("") : '<div class="panel-empty-state"><p class="panel-kicker">Portfólio vazio</p><h3>O próximo case começa aqui.</h3></div>';
      root.innerHTML = shell(`<main class="panel-page"><header class="panel-page-header"><div><p class="panel-kicker">Painel editorial</p><h1>Cases em movimento.</h1><p>Administre os trabalhos de Marketing e Tecnologia.</p></div><button class="button" data-new-case>Novo case <span>↗</span></button></header><section class="panel-collection"><header class="panel-collection__heading"><div><p class="panel-kicker">Biblioteca</p><h2>Cases cadastrados</h2></div><p>${cases.length} item(ns).</p></header><div class="panel-project-list">${cards}</div></section></main>`);
      controls(); document.querySelector("[data-new-case]")?.addEventListener("click", () => form());
      document.querySelectorAll("[data-edit]").forEach((button) => button.addEventListener("click", () => form(cases.find((item) => item.slug === button.dataset.edit))));
    } catch (error) { sessionStorage.removeItem(tokenKey); login(error.message); }
  }
  function form(item = {}) {
    root.innerHTML = shell(caseForm(item)); controls();
    const editor = document.querySelector("[data-case-form]"), grid = editor.querySelector("[data-media-grid]"), images = (item.images || []).map((image) => ({...image}));
    const updateMedia = () => { drawMedia(grid, images, updateMedia); editor.querySelector("[data-summary-images]").textContent = `${images.length} / 5`; };
    updateMedia();
    editor.querySelector("#id_images").addEventListener("change", (event) => {
      const files = [...event.target.files];
      if (images.length + files.length > 5) { alert("Cada case pode ter no máximo cinco imagens."); event.target.value = ""; return; }
      files.forEach((file) => images.push({file, preview: URL.createObjectURL(file)})); event.target.value = ""; updateMedia();
    });
    const sync = () => { editor.querySelector("[data-summary-title]").textContent = editor.title.value.trim() || "Case sem título"; editor.querySelector("[data-summary-front]").textContent = editor.front.selectedOptions[0]?.text || "Frente do case"; editor.querySelector("[data-summary-status]").textContent = editor.status.selectedOptions[0]?.text || "Rascunho"; };
    editor.addEventListener("input", sync); editor.addEventListener("change", sync); sync();
    editor.querySelectorAll("[data-count-for]").forEach((counter) => { const field = document.getElementById(counter.dataset.countFor); const count = () => counter.textContent = `${field.value.length} / ${field.maxLength}`; field.addEventListener("input", count); count(); });
    editor.addEventListener("submit", async (event) => {
      event.preventDefault(); const message = editor.querySelector("[data-form-error]"), submit = editor.querySelector("button[type=submit]"); message.hidden = true; submit.disabled = true;
      try {
        for (const image of images.filter((entry) => entry.file)) { const upload = new FormData(); upload.append("image", image.file); const {image: saved} = await api("/api/media", {method: "POST", body: upload}); Object.assign(image, saved); delete image.file; delete image.preview; }
        const data = Object.fromEntries(new FormData(editor)); data.featured = editor.featured.checked; data.images = images.map(({key, url, alt}) => ({key, url, alt}));
        if (item.slug) data.slug = item.slug;
        await api("/api/cases", {method: item.slug ? "PUT" : "POST", body: JSON.stringify(data)}); dashboard();
      } catch (error) { message.textContent = error.message; message.hidden = false; submit.disabled = false; }
    });
  }
  function login(message = "") {
    root.innerHTML = `<main class="panel-login"><section class="panel-login__brand"><div class="panel-login__brand-inner"><a class="brand" href="/"><span class="brand-word">PRISMA</span></a><div class="panel-login__statement"><p class="panel-kicker">Área editorial</p><h1>Ideias em <em>movimento.</em></h1><p>Um espaço de trabalho para registrar e publicar os cases da Prisma.</p></div></div></section><section class="panel-login__access"><div class="panel-login__form-shell"><p class="panel-kicker">Acesso da equipe</p><h2>Entrar no painel.</h2><form class="panel-login-form" data-login-form><div class="panel-field"><label for="password">Senha</label><input class="panel-control" id="password" name="password" type="password" required autocomplete="current-password"></div>${message ? `<p class="panel-form-alert">${esc(message)}</p>` : ""}<button class="button panel-login__submit" type="submit">Entrar <span>→</span></button></form></div></section></main>`;
    root.querySelector("[data-login-form]").addEventListener("submit", async (event) => { event.preventDefault(); try { const {token} = await api("/api/session", {method: "POST", body: JSON.stringify({password: event.target.password.value})}); sessionStorage.setItem(tokenKey, token); dashboard(); } catch (error) { login(error.message); } });
  }
  sessionStorage.getItem(tokenKey) ? dashboard() : login();
})();
